export const HTML_LESSON_STYLE = ".pixel-app,.pixel-setup{color:#273f3a;background:#fffdf8;font-family:inherit;box-sizing:border-box}\n.pixel-app *,.pixel-setup *{box-sizing:border-box}\n.pixel-app{width:100%;max-width:1120px;margin:auto;padding:clamp(16px,3vw,36px);border-radius:22px}\n.pixel-app header{margin-bottom:20px}.pixel-kicker{font-size:.8rem;font-weight:800;color:#287467;letter-spacing:.04em}\n.pixel-app h2,.pixel-setup h2{margin:6px 0 10px;font-size:clamp(1.3rem,3vw,2rem);overflow-wrap:anywhere}.pixel-app h3{font-size:1rem;margin:0 0 10px}\n.pixel-instructions{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6;max-height:8em;overflow:auto}\n.pixel-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(220px,310px);gap:28px;align-items:start}\n.pixel-grid{display:grid;grid-template-rows:repeat(var(--pixel-size),1fr);width:100%;aspect-ratio:1;max-width:620px;border:2px solid #49776a;border-radius:8px;overflow:hidden;touch-action:none;user-select:none;background:#c3d2cd}\n.pixel-row{display:grid;grid-template-columns:repeat(var(--pixel-size),minmax(0,1fr));min-height:0}\n.pixel-cell{display:block!important;width:100%;height:100%;min-width:0!important;min-height:0!important;padding:0!important;border:0!important;border-right:1px solid #9cad9a88!important;border-bottom:1px solid #9cad9a88!important;border-radius:0!important;cursor:crosshair;touch-action:none;box-shadow:none!important}\n.pixel-cell:focus-visible{outline:3px solid #ffb300!important;outline-offset:-4px;position:relative;z-index:1}\n.pixel-palette{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:16px}.pixel-app button,.pixel-setup button{font:inherit;font-weight:700;border:1px solid #c4d4cc;border-radius:12px;background:#fff;min-height:44px;padding:10px 13px;color:inherit;cursor:pointer;touch-action:manipulation}\n.pixel-app button:disabled,.pixel-setup button:disabled{opacity:.55;cursor:default}.pixel-app button:focus-visible,.pixel-setup button:focus-visible,.pixel-setup input:focus-visible,.pixel-setup textarea:focus-visible,.pixel-setup select:focus-visible{outline:3px solid #d99512;outline-offset:3px}\n.pixel-palette .pixel-color{min-width:44px;min-height:44px;padding:8px;border:2px solid #afbcb5;box-shadow:inset 0 0 0 1px #ffffff55}.pixel-color[aria-pressed=true]{outline:3px solid #287467;outline-offset:3px}\n.pixel-hint{font-size:.88rem;line-height:1.6;color:#526b60}.pixel-actions{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}\n.pixel-app .pixel-primary,.pixel-setup .pixel-primary{background:#287467;color:#fff;border-color:#287467}.pixel-tools>.pixel-primary{width:100%;line-height:1.4}\n.pixel-status{min-height:1.5em;font-size:.88rem;line-height:1.5;overflow-wrap:anywhere;margin:12px 0 0}.pixel-confirm{display:flex;flex-wrap:wrap;gap:8px;background:#fff1d4;border-radius:12px;padding:12px;margin:12px 0}.pixel-confirm[hidden]{display:none}.pixel-confirm>span{flex-basis:100%;font-size:.9rem;line-height:1.5}\n.pixel-setup{padding:24px;max-width:680px;margin:auto;border-radius:18px}.pixel-setup>p{line-height:1.6}.pixel-setup>label{display:grid;gap:8px;font-weight:700;margin:18px 0}.pixel-setup input[type=text],.pixel-setup textarea,.pixel-setup select{font:inherit;padding:12px;min-height:44px;width:100%;border:1px solid #bdcec5;border-radius:10px;background:#fff;color:#273f3a}.pixel-setup fieldset{border:1px solid #dce5df;border-radius:12px;padding:14px}.pixel-setup-palette{display:flex;flex-wrap:wrap;gap:12px}.pixel-color-field{display:grid;gap:6px;text-align:center;font-size:.85rem}.pixel-color-field input{width:44px;height:44px;padding:3px;border:1px solid #bdcec5;background:white;border-radius:8px}\n@media(max-width:680px){.pixel-workspace{grid-template-columns:minmax(0,1fr);gap:18px}.pixel-app{padding:16px;border-radius:0}.pixel-grid{max-width:480px;margin:auto}.pixel-tools{min-width:0}.pixel-palette{gap:10px}.pixel-setup{padding:16px}.pixel-app header{margin-bottom:16px}}\n@media(prefers-reduced-motion:reduce){.pixel-app *,.pixel-setup *{scroll-behavior:auto!important}}\n\n.gai-app-runtime{width:100%;max-width:1200px;margin:auto;padding:20px;background:#fffdf8;border-radius:18px;color:#273f3a;font-family:inherit;box-sizing:border-box}.gai-app-runtime *{box-sizing:border-box}.gai-app-kicker{font-size:.8rem;font-weight:800;color:#287467}.gai-app-runtime h2{font-size:clamp(1.15rem,2.5vw,1.8rem);margin:5px 0 8px;overflow-wrap:anywhere}.gai-app-instructions{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.5;font-size:.9rem;margin:0 0 14px;max-height:6em;overflow:auto}.gai-app-frame{display:block;border:0;box-shadow:0 0 0 1px #c7d9cf;background:white;border-radius:12px;width:100%;height:clamp(340px,58dvh,720px);min-height:340px}.gai-app-runtime footer{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding-top:14px}.gai-app-hint{font-size:.82rem;color:#526b60;line-height:1.5;flex:1 1 220px;margin:0}.gai-app-save{min-height:44px;font:inherit;font-weight:700;padding:12px 18px;border:0;border-radius:12px;background:#287467;color:white;cursor:pointer;touch-action:manipulation}.gai-app-save:disabled{opacity:.5;cursor:default}.gai-app-save:focus-visible{outline:3px solid #d99512;outline-offset:3px}.gai-app-status{width:100%;min-height:1.5em;margin:0;font-size:.85rem;line-height:1.5;overflow-wrap:anywhere}@media(max-width:680px){.gai-app-runtime{padding:12px;border-radius:12px}.gai-app-frame{height:58dvh;min-height:360px}.gai-app-save{width:100%}}\n\n/* 퀴즈 장: 편집기의 퀴즈 넣기 칸(.quiz-setup)과 발표 화면의 퀴즈(.quiz-app). 보기 색은 --quiz-c. */\n.quiz-setup{box-sizing:border-box;width:min(720px,100%);margin:auto;padding:22px 24px;background:#fffdf8;border:1px solid #d7e3d8;border-radius:18px;color:#273f3a;display:grid;gap:12px;box-shadow:0 10px 40px #0002}\n.quiz-setup *{box-sizing:border-box}\n.quiz-setup h2{margin:0;font-size:1.25rem}\n.quiz-setup h3{margin:4px 0 0;font-size:1rem}\n.quiz-setup-lead{margin:0;color:#4d625a;font-size:.9rem;line-height:1.55}\n.quiz-setup-field{display:grid;gap:6px;font-weight:700;font-size:.9rem}\n.quiz-setup-field textarea,.quiz-setup-field input,.quiz-setup-field select,.quiz-setup-ai select,.quiz-setup-ai input[type=text]{font:inherit;font-weight:400;padding:10px 12px;border:1px solid #c7d6cd;border-radius:10px;background:#fff;color:#273f3a;min-height:42px}\n.quiz-setup-choices{list-style:none;margin:0;padding:0;display:grid;gap:8px}\n.quiz-setup-choice{display:grid;grid-template-columns:38px 1fr auto;align-items:center;gap:8px}\n.quiz-setup-choice input[type=text]{border:2px solid var(--quiz-c)!important}\n.quiz-setup-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;background:var(--quiz-c);color:#fff;font-weight:900}\n.quiz-setup-right{display:flex;align-items:center;gap:4px;font-weight:600;font-size:.85rem;white-space:nowrap}\n.quiz-setup-row{display:flex;gap:10px;flex-wrap:wrap;align-items:end}\n.quiz-setup-grow{flex:1;min-width:220px}\n.quiz-setup-actions{display:flex;justify-content:flex-end;gap:8px}\n.quiz-setup-status{margin:0;min-height:1.3em;font-size:.88rem;color:#3d5a50}\n.quiz-setup-ai{display:grid;gap:10px;padding:14px;border-radius:14px;background:#f2f6ff;border:1px solid #d5ddf5}\n.quiz-setup-check{font-size:.9rem;font-weight:600}\n.quiz-setup-or{border-top:1px dashed #c7d6cd;padding-top:12px}\n.quiz-setup-picks{margin:0;padding:0;list-style:none;display:grid;gap:8px;max-height:280px;overflow:auto}\n.quiz-setup-pick{padding:10px 12px;border-radius:12px;background:#fff;border:1px solid #d7e3d8}\n.quiz-setup-pick ul{margin:6px 0 0;padding-left:22px;font-size:.88rem}\n.quiz-setup-right-choice{font-weight:800;color:#1f7a44}\n.quiz-setup-explain{margin:6px 0 0;font-size:.82rem;color:#4d625a}\n\n.quiz-app{box-sizing:border-box;width:100%;min-height:100%;margin:auto;padding:clamp(14px,3vw,48px);display:flex;flex-direction:column;gap:clamp(10px,1.6vw,24px);background:#f6f8fb;color:#1f2d3d;font-family:inherit}\n.quiz-app *{box-sizing:border-box}\n.quiz-head{display:flex;align-items:center;gap:14px}\n.quiz-kicker{padding:6px 16px;border-radius:999px;background:#273f3a;color:#fff;font-weight:800;font-size:clamp(14px,1.4vw,22px)}\n.quiz-clock{margin-left:auto;min-width:2.4em;text-align:center;font-size:clamp(22px,3vw,52px);font-weight:900;font-variant-numeric:tabular-nums;color:#273f3a}\n.quiz-count{font-weight:700;font-size:clamp(13px,1.3vw,22px);color:#3d5a50}\n.quiz-question{margin:0;font-size:clamp(22px,3.4vw,60px);line-height:1.25;font-weight:900;text-align:center;overflow-wrap:anywhere}\n.quiz-bar{height:clamp(8px,.8vw,14px);border-radius:99px;background:#dde5ef;overflow:hidden}\n.quiz-bar-fill{display:block;height:100%;background:linear-gradient(90deg,#22d3ee,#7c3aed);transform-origin:left;transition:transform .2s linear}\n.quiz-tiles{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:clamp(8px,1.2vw,20px);flex:1}\n.quiz-tiles-2{grid-template-rows:1fr}\n.quiz-tile{position:relative;display:flex;align-items:center;gap:clamp(10px,1.2vw,22px);min-height:clamp(64px,10vh,160px);padding:clamp(12px,1.6vw,28px);border-radius:clamp(12px,1.4vw,24px);background:var(--quiz-c);color:#fff;font-weight:800;font-size:clamp(18px,2.3vw,42px);line-height:1.2;box-shadow:0 6px 0 #0002;transition:opacity .25s,transform .25s,filter .25s}\n.quiz-mark{font-size:1.1em;flex:none;opacity:.95}\n.quiz-text{flex:1;overflow-wrap:anywhere}\n.quiz-n{flex:none;font-size:.8em;background:#ffffff33;border-radius:999px;padding:2px 12px}\n.quiz-n:empty{display:none}\n.quiz-tile.quiz-right{transform:scale(1.02);box-shadow:0 0 0 clamp(4px,.5vw,8px) #ffffff,0 0 0 clamp(8px,.9vw,14px) #30a46c,0 10px 24px #0003}\n.quiz-tile.quiz-right::after{content:'✓';position:absolute;right:clamp(10px,1.2vw,22px);top:50%;transform:translateY(-50%);font-size:1.3em}\n.quiz-tile.quiz-right .quiz-n{margin-right:1.6em}\n.quiz-tile.quiz-dim{opacity:.35;filter:saturate(.4)}\n.quiz-explain{margin:0;text-align:center;font-size:clamp(16px,1.8vw,30px);font-weight:700;color:#1f7a44}\n.quiz-rank{margin:0 auto;padding:0;list-style:none;display:grid;gap:clamp(6px,.8vw,12px);width:min(900px,100%)}\n.quiz-rank-row{display:grid;grid-template-columns:5em 1fr auto;align-items:center;gap:12px;padding:clamp(10px,1.1vw,18px) clamp(14px,1.6vw,26px);border-radius:16px;background:#fff;font-size:clamp(16px,2vw,34px);font-weight:700;box-shadow:0 3px 12px #0001}\n.quiz-rank-1{background:linear-gradient(90deg,#fff4c2,#ffffff);border:2px solid #e9a23b}\n.quiz-rank-2{border:2px solid #b6c2cf}\n.quiz-rank-3{border:2px solid #d8a47f}\n.quiz-app[data-phase=ranking] .quiz-tiles,.quiz-app[data-phase=ranking] .quiz-bar{display:none}\n.quiz-app[data-phase=shown] .quiz-bar,.quiz-app[data-phase=ready] .quiz-bar{visibility:hidden}\n.quiz-tiles-3 .quiz-tile:last-child{grid-column:1/-1;justify-self:center;width:calc(50% - clamp(4px,.6vw,10px))}\n.quiz-actions{display:flex;justify-content:center;gap:12px;flex-wrap:wrap}\n/* 발표 막대 단추(.cv-show-key)의 모양을 이긴다: 밝은 퀴즈 판 위의 큰 단추 */\n.quiz-app .quiz-btn{display:inline-flex;align-items:center;justify-content:center;font:inherit;font-weight:800;font-size:clamp(15px,1.4vw,24px);min-height:clamp(44px,4.6vw,64px);padding:10px clamp(18px,2vw,32px);border-radius:999px;border:2px solid #273f3a;background:#fff;color:#273f3a;cursor:pointer}\n.quiz-app .quiz-btn:hover{background:#eef3f0}\n.quiz-app .quiz-btn.quiz-primary{background:#273f3a;color:#fff}\n.quiz-app .quiz-btn.quiz-primary:hover{background:#1c2f2b}\n.quiz-app .quiz-btn:disabled{opacity:.5;cursor:default}\n.quiz-btn:focus-visible{outline:3px solid #d99512;outline-offset:3px}\n.quiz-status{margin:0;min-height:1.4em;text-align:center;font-size:clamp(14px,1.3vw,22px);color:#3d5a50}\n@media(max-width:680px){.quiz-tiles{grid-template-columns:1fr}.quiz-setup{padding:16px}.quiz-setup-choice{grid-template-columns:32px 1fr auto}}\n@media(prefers-reduced-motion:reduce){.quiz-tile,.quiz-bar-fill{transition:none}}\n\nbody{margin:0;background:#f0f4ef;color:#273f3a;font-family:system-ui,-apple-system,\"Malgun Gothic\",sans-serif}*{box-sizing:border-box}button{font:inherit;cursor:pointer;touch-action:manipulation}button:focus-visible{outline:3px solid #d99512;outline-offset:3px}.lesson-header{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:18px 28px;background:#fffdf8;border-bottom:1px solid #d7e3d8}.lesson-brand{font-size:.8rem;color:#287467;font-weight:800}.lesson-header h1{font-size:1.15rem;margin:5px 0;overflow-wrap:anywhere}.lesson-header button,.lesson-navigation button{min-height:44px;padding:10px 16px;border:1px solid #bdcec5;border-radius:12px;background:#fff;color:#273f3a;font-weight:700}.lesson-header .lesson-download{background:#287467;color:white;flex-shrink:0}.lesson-navigation{display:flex;align-items:center;justify-content:center;gap:12px;padding:12px;flex-wrap:wrap}.lesson-navigation button:disabled{opacity:.4;cursor:default}.lesson-count{min-width:9em;text-align:center;font-weight:700}.lesson-stage{margin:0 auto;max-width:1280px;padding:0 20px;outline:0}.lesson-scene{position:relative;animation:lesson-enter .22s ease-out}.lesson-slide{display:block;width:100%;height:auto;max-height:calc(100dvh - 240px);min-height:120px;object-fit:contain;border-radius:12px;background:#e5e9e2}.lesson-start{position:absolute;bottom:8%;left:50%;transform:translateX(-50%);padding:16px 30px;border-radius:999px;background:#287467;color:white;font-size:1.1rem;font-weight:800;border:3px solid white;box-shadow:0 3px 20px #0003;min-height:48px;white-space:nowrap}.lesson-status{min-height:1.5em;max-width:1000px;margin:16px auto 0;padding:0 20px;text-align:center;line-height:1.6;font-size:.9rem}.lesson-footer{text-align:center;padding:10px 20px 20px;color:#526b60;font-size:.8rem}.lesson-activity .pixel-app{max-width:1120px}@keyframes lesson-enter{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}@media(max-width:680px){.lesson-header{padding:12px;gap:10px;align-items:start;flex-wrap:wrap}.lesson-header h1{font-size:1rem}.lesson-header button{font-size:.85rem}.lesson-stage{padding:0 8px}.lesson-navigation{gap:6px}.lesson-navigation button{padding:8px 12px}.lesson-start{font-size:1rem;padding:12px 24px}.lesson-count{min-width:7em}.lesson-activity .pixel-app{border-radius:12px}.lesson-slide{max-height:65dvh}}@media(prefers-reduced-motion:reduce){.lesson-scene{animation:none}}\n.lesson-downloads{display:flex;flex-wrap:wrap;gap:8px}.lesson-header .lesson-download{white-space:normal;max-width:100%}\n.lesson-header .lesson-present{background:#1d3f8f}\n.lesson-show{position:fixed;inset:0;z-index:50;display:grid;place-items:center;background:#000;cursor:pointer;overflow:hidden}\n.lesson-show>.lesson-header,.lesson-show>.lesson-navigation,.lesson-show>.lesson-status,.lesson-show>.lesson-footer{display:none}\n.lesson-show .lesson-stage{max-width:none;padding:0;width:min(100vw,calc(100dvh * var(--lesson-ratio,1.7778)))}\n.lesson-show .lesson-slide{max-height:100dvh;border-radius:0;background:#000}\n.lesson-show .lesson-activity{width:100vw;height:calc(100dvh - 70px);overflow:auto;background:#f1f7f3;cursor:auto;display:flex;align-items:safe center;justify-content:center}\n.lesson-show:has(.lesson-activity) .lesson-stage{width:100vw}\n.lesson-show-bar{position:absolute;left:50%;bottom:14px;transform:translateX(-50%);z-index:10;display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:999px;background:rgba(20,24,34,.72);color:#fff;transition:opacity .35s;cursor:default}\n@media(hover:hover){.lesson-show[data-calm]{cursor:none}.lesson-show[data-calm] .lesson-show-bar:not(:focus-within){opacity:0}}\n.lesson-show-count{min-width:4.2em;text-align:center;font-weight:800;font-variant-numeric:tabular-nums}\n.lesson-effects-frame { position:relative; container-type:inline-size; margin:auto; width:min(100%,calc((100dvh - 240px) * var(--lesson-ratio))); aspect-ratio:var(--lesson-ratio); overflow:hidden; border-radius:12px; }\n.lesson-effects-frame .lesson-slide { width:100%; height:100%; min-height:0; max-height:none; }\n.lesson-effects-frame [data-effect-trigger]:focus-visible { outline:3px dashed #249486; outline-offset:2px; }\n@media(max-width:680px) { .lesson-effects-frame { width:min(100%,calc(65dvh * var(--lesson-ratio))); } }\n.lesson-show .lesson-effects-frame { width:100%; border-radius:0; }\n.lesson-show-key{display:inline-flex;align-items:center;min-height:36px;padding:4px 12px;border:0;border-radius:999px;background:rgba(255,255,255,.16);color:#fff;font-weight:800;white-space:nowrap}\n.lesson-show-key:hover{background:rgba(255,255,255,.3)}.lesson-show-key[hidden]{display:none}\n@media(max-width:960px){.lesson-show-bar{left:8px;right:8px;width:max-content;margin:0 auto;transform:none;flex-wrap:wrap;justify-content:center;border-radius:18px;max-width:calc(100vw - 16px)}.lesson-show-key{min-height:44px;padding:8px 10px}}\n";
